//! Billing: the Rust provider fixture.
//!
//! Each module exercises a case the brief's Rust row cares about (brief §4.4):
//! traits with several implementations, `dyn` calls, a generic impl block,
//! closures and functions used as values, a declarative macro, and local
//! bindings.

#[macro_use]
mod macros;
pub mod charge;
pub mod ledger;
pub mod pipeline;

pub use charge::{Apply, Charge, Discount, Fee};
pub use ledger::Ledger;

/// Runs every adjustment over `total` through the pipeline.
pub fn settle(total: i64) -> i64 {
    let adjustments: Vec<Box<dyn Apply>> = vec![Box::new(Fee(3)), Box::new(Discount(2))];
    let mut ledger = Ledger::default();
    let settled = pipeline::run(total, &adjustments, &mut ledger);
    log_line!(ledger, "settled");
    settled
}

//! A small ledger the pipeline records into.

/// Amounts recorded in order.
#[derive(Debug, Default)]
pub struct Ledger {
    /// Every recorded amount.
    pub entries: Vec<i64>,
}

impl Ledger {
    /// Records `amount`.
    pub fn record(&mut self, amount: i64) {
        self.entries.push(amount);
    }

    /// Writes a labelled line of the latest amount.
    pub fn line(&self, label: &str) -> String {
        let latest = self.entries.last().copied().unwrap_or_default();
        format!("{label}: {latest}")
    }
}

/// A second inherent impl block. Its `Self` gives the block itself a SCIP
/// symbol, `ledger/impl#[Ledger]` (V97), which is a container, not a symbol.
impl Ledger {
    /// The recorded amounts: a getter named like its field.
    pub fn entries(&self) -> &[i64] {
        &self.entries
    }

    /// A ledger holding `entries`.
    pub fn with(entries: Vec<i64>) -> Self {
        Self { entries }
    }
}

/// Limits for totals. A module (type namespace) and a function (value
/// namespace) share the name `totals`, as Rust allows.
pub mod totals {
    /// The largest total `totals` reports.
    pub const MAX: i64 = i64::MAX;
}

/// The ledger's total, capped at `totals::MAX`.
pub fn totals(_ledger: &Ledger) -> i64 {
    totals::MAX
}

//! A trait with several implementations, one of them a generic impl block.

/// Something that adjusts an amount.
pub trait Apply {
    /// Returns `amount` adjusted.
    fn apply(&self, amount: i64) -> i64;
}

/// A flat fee added to the amount.
pub struct Fee(pub i64);

/// A flat discount taken off the amount.
pub struct Discount(pub i64);

/// A charge carrying some payload `T`.
pub struct Charge<T> {
    /// The payload.
    pub payload: T,
    /// The amount the charge adds.
    pub amount: i64,
}

impl Apply for Fee {
    fn apply(&self, amount: i64) -> i64 {
        amount + self.0
    }
}

impl Apply for Discount {
    fn apply(&self, amount: i64) -> i64 {
        amount - self.0
    }
}

impl<T> Apply for Charge<T> {
    fn apply(&self, amount: i64) -> i64 {
        amount + self.amount
    }
}

/// Doubles an amount; used as a value in `pipeline`.
pub fn double(amount: i64) -> i64 {
    amount * 2
}

